    me->DefGlobalIndex = 0x1234;
    me->PlayerNumber = -2;
    me->m_type = 1;
    me->PDef = &g_def;
    g_def.LeaveDeadCreature = 1;
    me->LeaveDeadBodyOverride = 1;
    me->LeaveExperienceOrbsOverride = 1;
    g_world.MessageEventManager = &g_manager;
