    Game->SetThingHasInformation(Me, false, false, false);
    Game->EntitySetAsKillable(Me, false, true);
    Game->SetIsPushableByHero(CScriptThing(Me, CScriptThing::InlineCopy()), false);
    Game->SetHeroGuideToShowQuestCardsWhenSpokenTo(false);
    Game->EntityTeleportToThing(Me, Game->GetThingWithScriptName("M_DepartureTeacherStand"), false);
    CScriptGameResourceObjectScriptedThingBase scripted;
    if (scripted.IsScripting())
        scripted.Release();
    while (!Game->StartScriptingEntity(Me, scripted, 4)) {
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating()) return;
    }
    if (IsActiveThreadTerminating()) return;
    bool departureInactive = !Game->IsQuestActive("Q_GuildTrainingWoodsDeparture");
    if (departureInactive) {
        if (IsActiveThreadTerminating()) return;
        {
        CScriptGameResourceObjectScriptedThingBase hero;
        if (hero.IsScripting())
            hero.Release();
        while (!Game->StartScriptingEntity(Game->GetHero(), hero, 4)) {
            Game->NewScriptFrame();
            if (IsActiveThreadTerminating()) return;
        }
        if (IsActiveThreadTerminating()) return;
        CCutsceneCastMap cast;
        cast["GM"] = scripted;
        cast["HERO"] = hero;
        CScriptGameResourceObjectMovieBase movie;
