void NScript::CQ_TraderConflictEvilScript::CTC_BanditFollower::Main()
{
    {
        CIsThingAlive filter(Me);
        SetPredicate(filter);
    }
    Game->NewScriptFrame();
    if (IsActiveThreadTerminating()) return;
    CScriptGameResourceObjectScriptedThingBase scripted;
    Game->EntityAttachToScript(Me, Game->GetActiveQuestName());
    Game->EntitySetInFaction(Me, "FACTION_BANDITS_FRIENDLY");
    Game->MiniMapAddMarker(Me, "HUD_ORB_GREEN_SMALL");
    Game->EntitySetThingAsAllyOfThing(Me, Game->GetHero());
    Game->EntitySetThingAsAllyOfThing(Game->GetHero(), Me);
    Game->EntitySetAsMirroringHeroEnemyRelationsWhileFollowing(Me, false);
    while (!ParentClass->QuestStartScreened) {
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating()) return;
    }
    if (IsActiveThreadTerminating()) return;
    Game->EntityFollowThing(Me, Game->GetHero(), 1.0f, true);
    Game->AddQuestInfoBarHealth(Me, CRGBColour(255, 0, 0, 255), "HUD_QUEST_ICON_BANDIT", 1.0f);
    while (!ParentClass->MissionSucceeded) {
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating()) return;
        bool talkedTo = !SetAgainstHero && Me.MsgIsTalkedToBy("SCRIPT_NAME_HERO");
        if (talkedTo) {
            if (IsActiveThreadTerminating()) return;
            if (scripted.IsScripting())
                scripted.Release();
            while (!Game->StartScriptingEntity(Me, scripted, 4)) {
                Game->NewScriptFrame();
                if (IsActiveThreadTerminating()) return;
            }
            if (IsActiveThreadTerminating()) return;
            CScriptGameResourceObjectMovieBase movie;
            Game->StartMovieSequence("", movie);
            GameCalls* game = Game;
            game->PauseAllNonScriptedEntities(true);
            if (Game->GetHealth(scripted.GetScriptThing()) > 0.0f) {
                scripted.Speak(Game->GetHero(), "TEXT_QST_B12_OPENING_BANDIT_ON_SPEAK_TO", 2, false, true, false);
                while (scripted.IsPerformingScriptTask()) {
                    Game->NewScriptFrame();
                    if (IsActiveThreadTerminating()) {
                        game->PauseAllNonScriptedEntities(false);
                        return;
                    }
                }
                if (IsActiveThreadTerminating()) {
                    game->PauseAllNonScriptedEntities(false);
                    return;
                }
            }
            game->PauseAllNonScriptedEntities(false);
        }
        bool hitByHero = !SetAgainstHero
                      && (Me.MsgIsHitBy("SCRIPT_NAME_HERO")
                          || (Me.MsgIsHitByAnySpecialAbilityFrom("SCRIPT_NAME_HERO")
                              && !Me.MsgIsHitBySpecialAbilityFrom(14, "SCRIPT_NAME_HERO")));
        if (hitByHero) {
            if (IsActiveThreadTerminating()) return;
            if (!HitWarning) {
                if (IsActiveThreadTerminating()) return;
                long conversation = Game->AddNewConversation(Me, false, false);
                Game->AddPersonToConversation(conversation, Game->GetHero());
                Game->AddLineToConversation(conversation, "TEXT_QST_B12_BANDIT_FOLLOWER_ON_HIT_10", false, Me, Game->GetHero());
                HitWarning = true;
            }
            else if (!ParentClass->HeroAttackedBandit) {
                if (IsActiveThreadTerminating()) return;
                CScriptThing fighter = Game->GetNearestWithScriptName(Me, "TC_BanditFighter");
                if (IsDistanceBetweenThingsUnder(Me, fighter, 15.0f)) {
                    if (IsActiveThreadTerminating()) return;
                    ParentClass->HeroAttackedBandit = true;
                }
                Game->EntityStopFollowing(Me);
                Game->GiveThingBestEnemyTarget(Me, Game->GetHero());
                Game->EntityUnsetThingAsAllyOfThing(Me, Game->GetHero());
                Game->EntityUnsetThingAsAllyOfThing(Game->GetHero(), Me);
                SetAgainstHero = true;
            }
        }
        if (!SetAgainstHero && ParentClass->HeroAttackedBandit && IsDistanceBetweenThingsUnder(Me, Game->GetHero(), 15.0f)) {
            if (IsActiveThreadTerminating()) return;
            long conversation = Game->AddNewConversation(Me, false, false);
            Game->AddPersonToConversation(conversation, Game->GetHero());
            Game->AddLineToConversation(conversation, "TEXT_QST_B12_BANDIT_FOLLOWER_SEEKING_REVENGE_10", false, Me, Game->GetHero());
            Game->EntityStopFollowing(Me);
            Game->GiveThingBestEnemyTarget(Me, Game->GetHero());
            Game->EntityUnsetThingAsAllyOfThing(Me, Game->GetHero());
            Game->EntityUnsetThingAsAllyOfThing(Game->GetHero(), Me);
            SetAgainstHero = true;
        }
    }
    if (IsActiveThreadTerminating()) return;
    Game->RemoveThing(Me, false, true);
}

