CResourcePImp::~CResourcePImp() { }
CScriptGameResourceObjectScriptedThingBase::~CScriptGameResourceObjectScriptedThingBase() { }
bool CScriptGameResourceObjectScriptedThingBase::IsScripting() { return false; }
void CScriptGameResourceObjectScriptedThingBase::Release() { }
void CScriptGameResourceObjectScriptedThingBase::MoveToThing(const CScriptThing& thing, float speed, EScriptEntityMoveType moveType, bool a, bool b, bool c, bool d) { (void)thing; (void)speed; (void)moveType; (void)a; (void)b; (void)c; (void)d; }
CScriptThing CScriptGameResourceObjectScriptedThingBase::GetScriptThing() const { CScriptThing thing(*g_me); thing.PImp_Data = &g_selfThing; return thing; }
void CScriptGameResourceObjectScriptedThingBase::Speak(const CScriptThing& listener, const char* text, ETextGroupSelectionMethod method, bool a, bool b, bool c)
{
    if (&listener == g_hero && std::strcmp(text, "TEXT_QST_B12_OPENING_BANDIT_ON_SPEAK_TO") == 0 && method == 2 && !a && b && !c) ++g_speak;
}
bool CScriptGameResourceObjectScriptedThingBase::IsPerformingScriptTask() const { return (++g_performing & 1) != 0; }
void NScript::CEntityScriptBase::v00() { }
void NScript::CEntityScriptBase::SetPredicate(CIsThingAlive& predicate) { (void)predicate; }
bool NScript::CEntityScriptBase::IsActiveThreadTerminating() const { return g_frame >= g_limit; }
void GameCalls::NewScriptFrame() const
{
    ++g_frame;
    if (g_frame == 2) g_parent.QuestStartScreened = true;
    if (g_frame == 9) g_parent.MissionSucceeded = true;
}
bool GameCalls::StartScriptingEntity(const CScriptThing& thing, CScriptGameResourceObjectScriptedThingBase& handle, EScriptAIPriority priority)
{
    (void)handle;
    return &thing == g_me && priority == 4 && ++g_startTries >= 1;
}
CScriptThing& GameCalls::GetHero() { return *g_hero; }
CScriptThing GameCalls::GetNearestWithScriptName(const CScriptThing& thing, const CCharString& name)
{
    CScriptThing result(thing);
    result.PImp_Data = Is(name, "TC_BanditFighter") ? &g_fighterMark : 0;
    return result;
}
void GameCalls::RemoveThing(const CScriptThing& thing, bool a, bool b) { if (&thing == g_me && !a && b) ++g_removed; }
void GameCalls::EntityFollowThing(const CScriptThing& thing, const CScriptThing& leader, float distance, bool a) const { if (&thing == g_me && &leader == g_hero && distance == 1.0f && a) ++g_follow; }
void GameCalls::EntityStopFollowing(const CScriptThing& thing) const { if (&thing == g_me) ++g_stopFollow; }
void GameCalls::EntitySetAsMirroringHeroEnemyRelationsWhileFollowing(const CScriptThing& thing, bool mirror) const { if (&thing == g_me && !mirror) ++g_mirror; }
float GameCalls::GetHealth(const CScriptThing& thing) const { return thing.PImp_Data == &g_selfThing ? 7.0f : 0.0f; }
long GameCalls::AddQuestInfoBarHealth(const CScriptThing& thing, const CRGBColour& colour, const CCharString& icon, float scale) const
{
    if (&thing == g_me && colour.R == 255 && colour.G == 0 && colour.B == 0 && colour.A == 255 && Is(icon, "HUD_QUEST_ICON_BANDIT") && scale == 1.0f) ++g_bar;
    return 1;
}
void GameCalls::MiniMapAddMarker(const CScriptThing& thing, const CCharString& marker) const { if (&thing == g_me && Is(marker, "HUD_ORB_GREEN_SMALL")) ++g_marker; }
long GameCalls::AddNewConversation(const CScriptThing& thing, bool a, bool b) const { (void)thing; (void)a; (void)b; return 4; }
void GameCalls::AddPersonToConversation(long conversation, const CScriptThing& person) const { (void)conversation; (void)person; }
void GameCalls::AddLineToConversation(long conversation, const CCharString& text, bool a, const CScriptThing& speaker, const CScriptThing& listener) const
{
    if (conversation != 4 || a || &speaker != g_me || &listener != g_hero) return;
    if (Is(text, "TEXT_QST_B12_BANDIT_FOLLOWER_ON_HIT_10")) ++g_onHit;
    if (Is(text, "TEXT_QST_B12_BANDIT_FOLLOWER_SEEKING_REVENGE_10")) ++g_revenge;
}
void GameCalls::StartMovieSequence(const CCharString& name, CScriptGameResourceObjectMovieBase& movie) { (void)movie; if (Is(name, "")) ++g_movies; }
void GameCalls::PauseAllNonScriptedEntities(bool pause) { if (pause) ++g_pauseOn; else ++g_pauseOff; }
void GameCalls::GiveThingBestEnemyTarget(const CScriptThing& thing, const CScriptThing& target) const { if (&thing == g_me && &target == g_hero) ++g_targets; }
void GameCalls::EntityAttachToScript(const CScriptThing& thing, const CCharString& script) const { if (&thing == g_me && Is(script, "Q_Test")) ++g_attached; }
void GameCalls::EntitySetThingAsAllyOfThing(const CScriptThing& thing, const CScriptThing& ally) const { if ((&thing == g_me && &ally == g_hero) || (&thing == g_hero && &ally == g_me)) ++g_allies; }
void GameCalls::EntityUnsetThingAsAllyOfThing(const CScriptThing& thing, const CScriptThing& ally) const { if ((&thing == g_me && &ally == g_hero) || (&thing == g_hero && &ally == g_me)) ++g_unallies; }
void GameCalls::EntitySetInFaction(const CScriptThing& thing, const CCharString& faction) const { if (&thing == g_me && Is(faction, "FACTION_BANDITS_FRIENDLY")) ++g_faction; }
CCharString GameCalls::GetActiveQuestName() const { return CCharString("Q_Test"); }
bool __fastcall IsDistanceBetweenThingsUnder(const CScriptThing& a, const CScriptThing& b, float distance)
{
    if (&a != g_me || distance != 15.0f) return false;
    if (&b == g_hero) return false;                       // the hero never comes close in this run
    return b.PImp_Data == &g_fighterMark;
}

int main()
{
    typedef NScript::CQ_TraderConflictEvilScript::CTC_BanditFollower CFollower;
    static double storage[(sizeof(CFollower) + sizeof(double) - 1) / sizeof(double)];
    CFollower& follower = *new (storage) CFollower(*reinterpret_cast<CFollower*>(storage));
    static double heroStorage[2];
    CScriptThing& hero = *new (heroStorage) CScriptThing(*reinterpret_cast<CScriptThing*>(heroStorage));
    follower.Game = new GameCalls;
    follower.ParentClass = &g_parent;
    follower.HitWarning = false; follower.SetAgainstHero = false;
    g_me = &follower.Me; g_hero = &hero;
    follower.Main();
    bool ok = g_attached == 1 && g_faction == 1 && g_marker == 1 && g_allies == 2 && g_mirror == 1 && g_follow == 1 && g_bar == 1;
    ok = ok && g_movies == 1 && g_pauseOn == 1 && g_pauseOff == 1 && g_speak == 1;          // talked to on frame 3
    ok = ok && g_onHit == 1 && follower.HitWarning;                                         // first hit on frame 5
    ok = ok && g_parent.HeroAttackedBandit && follower.SetAgainstHero && g_stopFollow == 1;  // second hit near a fighter
    ok = ok && g_targets == 1 && g_unallies == 2 && g_revenge == 0 && g_removed == 1 && g_frame == 9;
    if (!ok) { std::printf("00df80b0_TEST FAIL\n"); return 1; }
    std::printf("00df80b0_TEST PASS\n");
    return 0;
}

