void NScript::CQ_TraderConflictEvilScript::CTC_BanditFighter::Main()
{
    {
        CIsThingAlive filter(Me);
        SetPredicate(filter);
    }
    Game->NewScriptFrame();
    if (IsActiveThreadTerminating()) return;
    Game->EntitySetInFaction(Me, "FACTION_BANDITS_FRIENDLY");
    Game->MiniMapAddMarker(Me, "HUD_ORB_GREEN_SMALL");
    Game->EntitySetThingAsAllyOfThing(Me, Game->GetHero());
    Game->EntitySetThingAsAllyOfThing(Game->GetHero(), Me);
    while (!ParentClass->QuestStartScreened) {
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating()) return;
    }
    if (IsActiveThreadTerminating()) return;
    Game->GiveThingBestEnemyTarget(Me, Game->GetNearestWithScriptName(Me, "IsAGuard"));
    while (!ParentClass->PlayerEngaged) {
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating()) return;
        bool hitByOther = Me.MsgIsHitBy("")
                       && !Me.MsgIsHitBy("SCRIPT_NAME_HERO")
                       && (!Me.MsgIsHitByAnySpecialAbilityFrom("SCRIPT_NAME_HERO")
                           || Me.MsgIsHitBySpecialAbilityFrom(14, "SCRIPT_NAME_HERO"));
        if (hitByOther) {
            if (IsActiveThreadTerminating()) return;
            Game->ModifyThingHealth(Me, 100.0f, false);
        }
        else {
            bool hitByHero = Me.MsgIsHitBy("SCRIPT_NAME_HERO")
                          || (Me.MsgIsHitByAnySpecialAbilityFrom("SCRIPT_NAME_HERO")
                              && !Me.MsgIsHitBySpecialAbilityFrom(14, "SCRIPT_NAME_HERO"));
            if (hitByHero) {
                if (IsActiveThreadTerminating()) return;
                ParentClass->PlayerEngaged = true;
            }
        }
        if (IsDistanceBetweenThingsUnder(Me, Game->GetHero(), 15.0f)) {
            if (IsActiveThreadTerminating()) return;
            ParentClass->PlayerEngaged = true;
        }
    }
    if (IsActiveThreadTerminating()) return;
    while (!ParentClass->MissionSucceeded) {
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating()) return;
        bool hitByHero = Me.MsgIsHitBy("SCRIPT_NAME_HERO")
                      || (Me.MsgIsHitByAnySpecialAbilityFrom("SCRIPT_NAME_HERO")
                          && !Me.MsgIsHitBySpecialAbilityFrom(14, "SCRIPT_NAME_HERO"));
        if (hitByHero) {
            if (IsActiveThreadTerminating()) return;
            if (!HitWarning) {
                if (IsActiveThreadTerminating()) return;
                long conversation = Game->AddNewConversation(Me, false, false);
                Game->AddPersonToConversation(conversation, Game->GetHero());
                Game->AddLineToConversation(conversation, "TEXT_QST_B12_BANDIT_ON_HIT_10", false, Me, Game->GetHero());
                HitWarning = true;
            }
            else {
                if (IsActiveThreadTerminating()) return;
                CScriptThing fighter = Game->GetNearestWithScriptName(Me, "TC_BanditFighter");
                if (IsDistanceBetweenThingsUnder(Me, fighter, 15.0f)) {
                    if (IsActiveThreadTerminating()) return;
                    ParentClass->HeroAttackedBandit = true;
                }
            }
        }
        if (ParentClass->HeroAttackedBandit && IsDistanceBetweenThingsUnder(Me, Game->GetHero(), 15.0f)) {
            if (IsActiveThreadTerminating()) return;
            if (rand() % 5 == 0) {
                if (IsActiveThreadTerminating()) return;
                long conversation = Game->AddNewConversation(Me, false, false);
                Game->AddPersonToConversation(conversation, Game->GetHero());
                Game->AddLineToConversation(conversation, "TEXT_QST_B12_BANDIT_SEEKING_REVENGE_10", false, Me, Game->GetHero());
            }
            Game->GiveThingBestEnemyTarget(Me, Game->GetHero());
            Game->EntityUnsetThingAsAllyOfThing(Me, Game->GetHero());
            Game->EntityUnsetThingAsAllyOfThing(Game->GetHero(), Me);
            while (!ParentClass->MissionSucceeded) {
                Game->NewScriptFrame();
                if (IsActiveThreadTerminating()) return;
            }
            if (IsActiveThreadTerminating()) return;
        }
    }
    if (IsActiveThreadTerminating()) return;
    Game->RemoveThing(Me, false, true);
}


static int g_frame = 0, g_limit = 40;
static int g_heal = 0, g_faction = 0, g_marker = 0, g_allies = 0, g_unallies = 0, g_targets = 0, g_guardTarget = 0;
