void NScript::CEntityScriptBase::v00() { }
void NScript::CEntityScriptBase::SetPredicate(CIsThingAlive& predicate) { (void)predicate; }
bool NScript::CEntityScriptBase::IsActiveThreadTerminating() const { return g_frame >= g_limit; }
void GameCalls::NewScriptFrame() const
{
    ++g_frame;
    if (g_frame == 2) g_parent.QuestStartScreened = true;
    if (g_frame == 9) g_parent.MissionSucceeded = true;
}
CScriptThing& GameCalls::GetHero() { return *g_hero; }
CScriptThing GameCalls::GetNearestWithScriptName(const CScriptThing& thing, const CCharString& name)
{
    CScriptThing result(thing);
    result.PImp_Data = Is(name, "IsAGuard") ? (void*)&g_guardMark : Is(name, "TC_BanditFighter") ? (void*)&g_fighterMark : 0;
    return result;
}
void GameCalls::RemoveThing(const CScriptThing& thing, bool a, bool b) { if (&thing == g_me && !a && b) ++g_removed; }
void GameCalls::ModifyThingHealth(const CScriptThing& thing, float amount, bool canKill) const { if (&thing == g_me && amount == 100.0f && !canKill) ++g_heal; }
void GameCalls::MiniMapAddMarker(const CScriptThing& thing, const CCharString& marker) const { if (&thing == g_me && Is(marker, "HUD_ORB_GREEN_SMALL")) ++g_marker; }
long GameCalls::AddNewConversation(const CScriptThing& thing, bool a, bool b) const { (void)thing; (void)a; (void)b; return 3; }
void GameCalls::AddPersonToConversation(long conversation, const CScriptThing& person) const { (void)conversation; (void)person; }
void GameCalls::AddLineToConversation(long conversation, const CCharString& text, bool a, const CScriptThing& speaker, const CScriptThing& listener) const
{
    if (conversation != 3 || a || &speaker != g_me || &listener != g_hero) { ++g_otherLines; return; }
    if (Is(text, "TEXT_QST_B12_BANDIT_ON_HIT_10")) ++g_onHit;
    else if (Is(text, "TEXT_QST_B12_BANDIT_SEEKING_REVENGE_10")) ++g_revenge;
    else ++g_otherLines;
}
void GameCalls::GiveThingBestEnemyTarget(const CScriptThing& thing, const CScriptThing& target) const
{
    if (&thing != g_me) return;
    if (target.PImp_Data == &g_guardMark) ++g_guardTarget;
    if (&target == g_hero) ++g_targets;
}
void GameCalls::EntitySetThingAsAllyOfThing(const CScriptThing& thing, const CScriptThing& ally) const
{
    if ((&thing == g_me && &ally == g_hero) || (&thing == g_hero && &ally == g_me)) ++g_allies;
}
void GameCalls::EntityUnsetThingAsAllyOfThing(const CScriptThing& thing, const CScriptThing& ally) const
{
    if ((&thing == g_me && &ally == g_hero) || (&thing == g_hero && &ally == g_me)) ++g_unallies;
}
void GameCalls::EntitySetInFaction(const CScriptThing& thing, const CCharString& faction) const { if (&thing == g_me && Is(faction, "FACTION_BANDITS_FRIENDLY")) ++g_faction; }
bool __fastcall IsDistanceBetweenThingsUnder(const CScriptThing& a, const CScriptThing& b, float distance)
{
    if (&a != g_me || distance != 15.0f) return false;
    if (&b == g_hero) return g_frame >= 5;           // the hero walks up on frame 5
    return b.PImp_Data == &g_fighterMark;            // another fighter is always close by
}

int main()
{
    typedef NScript::CQ_TraderConflictEvilScript::CTC_BanditFighter CFighter;
    static double storage[(sizeof(CFighter) + sizeof(double) - 1) / sizeof(double)];
    CFighter& fighter = *new (storage) CFighter(*reinterpret_cast<CFighter*>(storage));
    static CScriptThing* hero = (CScriptThing*)std::malloc(sizeof(CScriptThing));
    fighter.Game = new GameCalls;
    fighter.ParentClass = &g_parent;
    fighter.HitWarning = false;
    g_me = &fighter.Me;
    g_hero = hero;
    fighter.Main();
    bool ok = g_faction == 1 && g_marker == 1 && g_allies == 2 && g_guardTarget == 1;
    ok = ok && g_heal == 1 && g_parent.PlayerEngaged;                            // healed on frame 4, engaged on frame 5
    ok = ok && g_onHit == 1 && fighter.HitWarning && g_parent.HeroAttackedBandit;  // warned on frame 6, attack on frame 7
    ok = ok && g_revenge <= 1 && g_targets == 1 && g_unallies == 2 && g_otherLines == 0;
    ok = ok && g_removed == 1 && g_frame == 9;
    if (!ok) { std::printf("00df8970_TEST FAIL\n"); return 1; }
    std::printf("00df8970_TEST PASS\n");
    return 0;
}

