bool GameCalls::StartScriptingEntity(const CScriptThing& thing, CScriptGameResourceObjectScriptedThingBase& object, EScriptAIPriority priority)
{
    (void)object;
    if (&thing != g_me || priority != 2) return false;
    if (++g_startTries < 2) return false;      // first try fails
    g_scripting = true;
    return true;
}
CScriptThing& GameCalls::GetHero() { return *g_hero; }
bool GameCalls::IsWearingClothingItem(const CScriptThing& thing, const CCharString& item)
{
    static const char* pieces[5] = { "OBJECT_HERO_SHIRT_BANDITCAMP", "OBJECT_HERO_TROUSERS_BANDITCAMP", "OBJECT_HERO_HAT_BANDITCAMP",
                                     "OBJECT_HERO_BOOTS_BANDITCAMP", "OBJECT_HERO_GLOVES_BANDITCAMP" };
    if (&thing != g_hero) return false;
    for (int i = 0; i < 5; ++i)
        if (std::strcmp(Text(item), pieces[i]) == 0) return (g_wearMask >> i) & 1;
    return false;
}
long GameCalls::AddNewConversation(const CScriptThing& thing, bool a, bool b) const { if (&thing == g_me && !a && !b) ++g_conversations; return 9; }
