void GameCalls::AddLineToConversation(long conversation, const CCharString& text, bool a, const CScriptThing& speaker, const CScriptThing& listener) const
{
    if (conversation == 9 && !a && &speaker == g_me && &listener == g_hero) { ++g_lines; g_lastLine = Text(text); }
}
bool __fastcall IsDistanceBetweenThingsUnder(const CScriptThing& a, const CScriptThing& b, float distance)
{
    return &a == g_me && &b == g_hero && distance == 15.0f && g_frame >= 3;   // the hero arrives on frame 3
}

typedef NScript::CQ_TraderConflictGoodScript::CTC_BanditGuard CGuard;
static bool Run(CGuard& guard, int wearMask, const char* expectedLine)
{
    g_frame = 0; g_limit = 8; g_startTries = 0; g_releases = 0; g_lines = 0; g_lastLine = 0; g_wearMask = wearMask;
    g_conversations = 0; g_people = 0;
    guard.Main();
    return g_lines == 1 && g_conversations == 1 && g_people == 1 && std::strcmp(g_lastLine, expectedLine) == 0
        && g_releases == 1 && g_frame == g_limit && g_startTries == 2;
}

