static inline void ReleaseScriptedControl(CScriptGameResourceObjectScriptedThingBase& handle)
{
    if (handle.IsScripting())
        handle.Release();
}

void NScript::CV_TravellingHeroesScript::CTH_ThunderBoy::Main()
{
    {
        CIsThingAlive filter(Me);
        SetPredicate(filter);
    }
    Game->NewScriptFrame();
    if (IsActiveThreadTerminating()) return;
    Game->SetThingPersistent(Me, true);
    if (GetMasterData()->PostSavePosition > 900) {
        if (IsActiveThreadTerminating()) return;
        Game->RemoveThing(Me, false, true);
    }
    Game->EntitySetAsUseMovementInActions(Me, false);
    Game->SetIsPushableByHero(CScriptThing(Me, CScriptThing::InlineCopy()), false);
    ReleaseScriptedControl(ParentClass->seh_Boy);
    while (!Game->StartScriptingEntity(Me, ParentClass->seh_Boy, 4)) {
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating()) return;
    }
    if (IsActiveThreadTerminating()) return;
    CScriptThing thunder = Game->GetThingWithScriptName("TH_Thunder");
    Game->EntityTeleportToThing(Me, Game->GetThingWithScriptName("TH_ThunderBoyMarker2"), false);
    Game->EntityForceToLookAtThing(Me, thunder);
    Game->SetLookForFiniteTime(CScriptThing(Me, CScriptThing::InlineCopy()), false);
    while (!ParentClass->ThunderSceneStarted) {
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating()) return;
        if (Me.MsgIsTalkedToBy("SCRIPT_NAME_HERO")) {
            if (IsActiveThreadTerminating()) return;
            ParentClass->ThunderKidsTalking = true;
            CScriptGameResourceObjectMovieBase movie;
            Game->StartMovieSequence("", movie);
            GameCalls* game = Game;
            game->PauseAllNonScriptedEntities(true);
            if (Game->GetHealth(ParentClass->seh_Boy.GetScriptThing()) > 0.0f) {
                ParentClass->seh_Boy.Speak(Game->GetHero(), "TEXT_QST_B14_THUNDER_BOYCHAT", 2, false, true, false);
                while (ParentClass->seh_Boy.IsPerformingScriptTask()) {
                    Game->NewScriptFrame();
                    if (IsActiveThreadTerminating()) {
                        game->PauseAllNonScriptedEntities(false);
                        return;
                    }
                }
                if (IsActiveThreadTerminating()) {
                    game->PauseAllNonScriptedEntities(false);
                    return;
                }
            }
            Game->EntitySetFacingAngleTowardsThing(Me, thunder, false);
            ParentClass->ThunderKidsTalking = false;
            game->PauseAllNonScriptedEntities(false);
        }
    }
    if (IsActiveThreadTerminating()) return;
    while (!ParentClass->ThunderSceneDone) {
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating()) return;
    }
    if (IsActiveThreadTerminating()) return;
    ParentClass->seh_Boy.MoveToThing(Game->GetThingWithScriptName("MK_TH_EXIT"), 1.0f, 1, false, true, false, true);
    for (;;) {
        if (IsDistanceBetweenThingsOver(Me, Game->GetHero(), 10.0f) && !Game->IsCameraPosOnScreen(Me.GetPos())) {
            if (IsActiveThreadTerminating()) return;
            Game->RemoveThing(Me, false, true);
            return;
        }
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating()) return;
    }
}

