bool GameCalls::IsCameraPosOnScreen(const C3DVector& position) const { return (const void*)&position == &g_position && g_frame < 11; }
void GameCalls::EntityTeleportToThing(const CScriptThing& thing, const CScriptThing& target, bool a) const { if (&thing == g_me && target.PImp.Data == (CScriptThingImpl*)&g_thingMarks[1] && !a) ++g_teleport; }
void GameCalls::EntitySetFacingAngleTowardsThing(const CScriptThing& thing, const CScriptThing& target, bool a) const
{
    if (&thing == g_me && target.PImp.Data == (CScriptThingImpl*)&g_thingMarks[0] && !a && g_parent->ThunderKidsTalking) ++g_facing;
}
void GameCalls::SetThingPersistent(const CScriptThing& thing, bool persistent) const { if (&thing == g_me && persistent) ++g_persistent; }
void GameCalls::EntityForceToLookAtThing(const CScriptThing& thing, const CScriptThing& target) const { if (&thing == g_me && target.PImp.Data == (CScriptThingImpl*)&g_thingMarks[0]) ++g_lookAt; }
void GameCalls::EntitySetAsUseMovementInActions(const CScriptThing& thing, bool use) const { if (&thing == g_me && !use) ++g_noMovement; }
void GameCalls::SetIsPushableByHero(CScriptThing thing, bool pushable) { if (thing.PImp.Data == g_me->PImp.Data && !pushable) ++g_notPushable; }
void GameCalls::SetLookForFiniteTime(CScriptThing thing, bool finite) { if (thing.PImp.Data == g_me->PImp.Data && !finite) ++g_finiteLook; }
bool __fastcall IsDistanceBetweenThingsOver(const CScriptThing& a, const CScriptThing& b, float distance) { return &a == g_me && &b == g_hero && distance == 10.0f && g_frame >= 10; }

static void Reset()
{
    g_frame = 0; g_persistent = g_removedEarly = g_removedLate = g_noMovement = g_notPushable = g_startTries = 0;
    g_teleport = g_lookAt = g_finiteLook = g_movies = g_pauseOn = g_pauseOff = g_speak = g_performing = g_facing = g_moveExit = 0;
    g_released = 0; g_scripting = true;
    g_parent->ThunderSceneStarted = false; g_parent->ThunderSceneDone = false; g_parent->ThunderKidsTalking = false;
}

int main()
{
    static double storage[(sizeof(CKid) + sizeof(double) - 1) / sizeof(double)];
    CKid& kid = *new (storage) CKid(*reinterpret_cast<CKid*>(storage));
    static double heroStorage[2];
    CScriptThing& hero = *new (heroStorage) CScriptThing(*reinterpret_cast<CScriptThing*>(heroStorage));
    static NScript::CV_TravellingHeroesScript parent;
    static NScript::CQ_SunnyvaleMasterData master;
    kid.Game = new GameCalls;
    kid.ParentClass = &parent;
    kid.PMasterData = &master;
    kid.Me.PImp.Data = (CScriptThingImpl*)&kid;
    g_me = &kid.Me; g_hero = &hero; g_proto = &kid.Me; g_parent = &parent;
    master.PostSavePosition = 10;
    Reset();
    kid.Main();
    bool ok = g_persistent == 1 && g_removedEarly == 0 && g_noMovement == 1 && g_notPushable == 1 && g_released == 1 && g_startTries == 2;
    ok = ok && g_teleport == 1 && g_lookAt == 1 && g_finiteLook == 1;
    ok = ok && g_movies == 1 && g_pauseOn == 1 && g_pauseOff == 1 && g_speak == 1 && g_performing == 3 && g_facing == 1;
    ok = ok && !parent.ThunderKidsTalking && g_moveExit == 1 && g_removedLate == 1 && g_frame == 11;
    // past gameflow position 900 the kid is removed straight away (and the script carries on)
    master.PostSavePosition = 901;
    Reset();
    kid.Main();
    ok = ok && g_removedEarly == 1 && g_removedLate == 1;
    // a thread that terminates while the kid is still chatting un-pauses the world before leaving
    master.PostSavePosition = 0;
    Reset();
    g_limit = 4;
    kid.Main();
    ok = ok && g_pauseOn == 1 && g_pauseOff == 1 && g_speak == 1 && g_moveExit == 0;
    if (!ok) { std::printf("00edf3a0_TEST FAIL\n"); return 1; }
    std::printf("00edf3a0_TEST PASS\n");
    return 0;
}

