        if (IsDistanceBetweenThingsOver(Me, Game->GetHero(), 10.0f) && !Game->IsCameraPosOnScreen(Me.GetPos())) {
            if (IsActiveThreadTerminating()) return;
            Game->RemoveThing(Me, false, true);
