static void Reset()
{
    g_frame = 0; g_persistent = g_removedEarly = g_removedLate = g_noMovement = g_notPushable = g_startTries = 0;
    g_teleport = g_lookAt = g_finiteLook = g_movies = g_pauseOn = g_pauseOff = g_speak = g_performing = g_facing = g_moveExit = 0;
    g_released = 0; g_scripting = true;
    g_parent->ThunderSceneStarted = false; g_parent->ThunderSceneDone = false; g_parent->ThunderKidsTalking = false;
}

int main()
{
    static double storage[(sizeof(CKid) + sizeof(double) - 1) / sizeof(double)];
    CKid& kid = *new (storage) CKid(*reinterpret_cast<CKid*>(storage));
    static double heroStorage[2];
    CScriptThing& hero = *new (heroStorage) CScriptThing(*reinterpret_cast<CScriptThing*>(heroStorage));
    static NScript::CV_TravellingHeroesScript parent;
    static NScript::CQ_SunnyvaleMasterData master;
