    kid.ParentClass = &parent;
    kid.PMasterData = &master;
    kid.Me.PImp.Data = (CScriptThingImpl*)&kid;
    g_me = &kid.Me; g_hero = &hero; g_proto = &kid.Me; g_parent = &parent;
    master.PostSavePosition = 10;
    Reset();
    kid.Main();
    bool ok = g_persistent == 1 && g_removedEarly == 0 && g_noMovement == 1 && g_notPushable == 1 && g_released == 1 && g_startTries == 2;
    ok = ok && g_teleport == 1 && g_lookAt == 1 && g_finiteLook == 1;
    ok = ok && g_movies == 1 && g_pauseOn == 1 && g_pauseOff == 1 && g_speak == 1 && g_performing == 3 && g_facing == 1;
    ok = ok && !parent.ThunderKidsTalking && g_moveExit == 1 && g_removedLate == 1 && g_frame == 11;
    // past gameflow position 900 the kid is removed straight away (and the script carries on)
    master.PostSavePosition = 901;
    Reset();
    kid.Main();
    ok = ok && g_removedEarly == 1 && g_removedLate == 1;
