    g_trollImpl.DiesOnFrame = 5;
    barrier.Main();
    bool ok = g_badArgs == 0 && g_effectCount == 6 && g_removedEffects == 2 && g_removedMe == 1 && g_frame == 5;
    ok = ok && std::strcmp(g_effects[2].Name, "NEW_RED_FORCEFIELD_IDLE_01") == 0 && std::strcmp(g_effects[3].Name, "NEW_RED_FORCEFIELD_IDLE_02") == 0;
