{
    if (&listener != g_hero || method != 0 || a || !b || c) return;
    if (std::strcmp(text, "TEXT_QST_B14_MAZE_AFTERSCENE_TALK") == 0) ++g_talkLines;
    if (std::strcmp(text, "TEXT_QST_B14_MAZE_AFTERSCENE_HIT") == 0) ++g_hitLines;
}
