void GameCalls::NewScriptFrame() const { ++g_frame; if (g_frame == 2) g_parent.MazeCutsceneDone = true; }
bool GameCalls::StartScriptingEntity(const CScriptThing& thing, CScriptGameResourceObjectScriptedThingBase& handle, EScriptAIPriority priority)
{
    (void)handle;
    ++g_startTries;
    return &thing == g_me && priority == 4;
}
CScriptThing& GameCalls::GetHero() { return *g_hero; }
long GameCalls::GetAllThingsWithDefName(const CCharString& defName, vector<CScriptThing>& things) const
{
    if (!Is(defName, "CREATURE_RIVAL_HERO_MAZE")) return 0;
    things._M_start = (CScriptThing*)std::malloc(sizeof(CScriptThing) * 2);
    new (&things._M_start[0]) CScriptThing(*g_me);
    new (&things._M_start[1]) CScriptThing(*g_me);
    things._M_start[1].PImp.Data = (CScriptThingImpl*)&g_otherMaze;
    things._M_finish = things._M_start + g_mazeCount;
    things._M_end_of_storage = things._M_start + 2;
    return g_mazeCount;
}
void GameCalls::RemoveThing(const CScriptThing& thing, bool a, bool b) const { if (&thing == g_me && !a && b) ++g_removed; }
float GameCalls::GetHealth(const CScriptThing& thing) const { return thing.PImp.Data == (CScriptThingImpl*)&g_kidThing ? 5.0f : 0.0f; }
void GameCalls::StartMovieSequence(const CCharString& name, CScriptGameResourceObjectMovieBase& movie) { (void)movie; if (Is(name, "")) ++g_movies; }
void GameCalls::PauseAllNonScriptedEntities(bool pause) { if (pause) ++g_pauseOn; else ++g_pauseOff; }
void GameCalls::EntityTeleportToThing(const CScriptThing& thing, const CScriptThing& target, bool a) const
{
    if (thing.PImp.Data == (CScriptThingImpl*)&g_otherMaze && &target == g_me && !a) ++g_teleports;
}
void GameCalls::SetThingPersistent(const CScriptThing& thing, bool persistent) const { if (&thing == g_me && persistent) ++g_persistent; }
bool __fastcall IsDistanceBetweenThingsUnder(const CScriptThing& a, const CScriptThing& b, float distance) { return &a == g_me && &b == g_hero && distance == 20.0f && g_frame < 6; }

int main()
{
    typedef NScript::CV_TravellingHeroesScript::CTH_Maze CMaze;
    static double storage[(sizeof(CMaze) + sizeof(double) - 1) / sizeof(double)];
    CMaze& maze = *new (storage) CMaze(*reinterpret_cast<CMaze*>(storage));
    static double heroStorage[2];
    CScriptThing& hero = *new (heroStorage) CScriptThing(*reinterpret_cast<CScriptThing*>(heroStorage));
    maze.Game = new GameCalls;
    maze.ParentClass = &g_parent;
    maze.Me.PImp.Data = (CScriptThingImpl*)&maze;
    g_me = &maze.Me; g_hero = &hero;
    maze.Main();
    bool ok = g_persistent == 1 && g_teleports == 0 && g_startTries == 1 && g_movies == 2 && g_pauseOn == 2 && g_pauseOff == 2;
    ok = ok && g_talkLines == 1 && g_hitLines == 1 && g_removed == 1 && g_frame == 6;
    // a second rival maze in the world: teleport it onto Me and remove Me before carrying on
    g_frame = 0; g_mazeCount = 2; g_removed = 0; g_parent.MazeCutsceneDone = true; g_limit = 2;
    maze.Main();
    ok = ok && g_teleports == 1 && g_removed == 2;      // removed early (the cutscene already ran) and after the teleport
    if (!ok) { std::printf("00ee1e40_TEST FAIL\n"); return 1; }
    std::printf("00ee1e40_TEST PASS\n");
    return 0;
}
